/**
 * Reads a color token's current value, for code that needs a concrete color and cannot use a
 * class or `var()`: a canvas, a WebGL scene, a map marker. The value follows the theme in
 * force on `element`, so a `.dark` subtree reads its dark value.
 *
 * Write `name` as a literal at the call site. Tailwind emits a theme variable only when a
 * scanned source file names it in full, so a name built from parts reads as unset.
 *
 * Browser only. It reads `document` when called, not when imported.
 *
 * @param name - The whole custom property name, such as `--color-solar-power-bright`.
 * @param element - Where the color is drawn. Defaults to the document root.
 * @returns The token's value as written in the stylesheet, or `undefined` when it is unset.
 */
export function themeColor(
  name: ThemeColorName,
  element?: Element,
): string | undefined;
